import pytest
from fastapi import FastAPI, Depends
from httpx import AsyncClient
import inspect
from fastapi.dependencies.models import Dependant

class AsyncCallDependency:
    async def __call__(self):
        return "hello"

def test_dependant_properties_with_class():
    # Test the properties directly on Dependant
    dep = Dependant(call=AsyncCallDependency)
    assert dep.is_coroutine_callable is False
    assert dep.is_async_gen_callable is False
    assert dep.is_gen_callable is False

@pytest.mark.anyio
async def test_app_with_class_dependency():
    app = FastAPI()

    @app.get("/")
    async def root(dep: AsyncCallDependency = Depends(AsyncCallDependency)):
        return {"message": dep}

    async with AsyncClient(app=app, base_url="http://test") as ac:
        response = await ac.get("/")
    assert response.status_code == 200
    assert response.json() == {"message": "hello"}

class SyncCallDependency:
    def __call__(self):
        return "hello"

def test_dependant_properties_with_sync_class():
    dep = Dependant(call=SyncCallDependency)
    assert dep.is_coroutine_callable is False
    assert dep.is_async_gen_callable is False
    assert dep.is_gen_callable is False

@pytest.mark.anyio
async def test_app_with_sync_class_dependency():
    app = FastAPI()

    @app.get("/")
    async def root(dep: SyncCallDependency = Depends(SyncCallDependency)):
        return {"message": dep}

    async with AsyncClient(app=app, base_url="http://test") as ac:
        response = await ac.get("/")
    assert response.status_code == 200
    assert response.json() == {"message": "hello"}

